        if ((h < rtEmptyH()) || (h > rtEmptyHMax())) {
            return 0;
        }
        if (w < rtEmptyW()) {
            return 0;
        }
        if (w > (h * rtEmptyAspect())) {
            return 0;
        }
        return (w / 100) * (h / 100);
